primes := [11, 13, 17, 19, 23, 29, 31, 37, 41];


printf "Using Kyng's algorithm\n";
for i in [1..#primes] do 
    p := primes[i];
    printf "p = %o\n", p;
    P2<x1,x2,x3> := ProjectiveSpace(GF(p), 2);
    f := eqns[i];
    C := Curve(Scheme(P2, f));
    time LPolynomial(C : Al := "Kyng");
end for;


